async function adoptCourse(settings){
 const next=makePlan(questions,settings);
 const ok=await mutate(s=>{
  const oldPlan=s.plan||[],oldMissions=s.missions||{},mapped={};
  if(oldPlan.length)s.history.push({id:id(),at:Date.now(),action:'Switched or updated 90-day course; original entries archived',oldSettings:s.settings,oldPlan,missions:oldMissions});
  for(const d of next){const prior=oldPlan.find(x=>x.learning?.title===d.learning.title&&!!x.repeat===!!d.repeat&&x.questions.join(',')===d.questions.join(',')&&(d.questions.length||x.learning?.week===d.learning.week));if(prior&&oldMissions[prior.date]){const {reviewIds,...entries}=oldMissions[prior.date];mapped[d.date]=entries;}}
  s.settings=settings;s.plan=next;s.missions=mapped;
 });
 if(ok){courseCursor=next.find(d=>!missionComplete(d))?.number||1;location.hash='today/'+courseCursor;}
 return ok;
}
function playgroundPool(){
 const learnedDay=selectedPlan()?.number||1;
 return questions.filter(q=>{
  if(playground.pool==='neetcode'&&q.sheet!=='NeetCode 150')return false;
  if(playground.pool==='java'&&q.url)return false;
  if(playground.pool==='course'&&q.tier!=='Core')return false;
  if(playground.topic&&(q.sheetTopic||q.topic)!==playground.topic)return false;
  if(playground.pattern&&q.pattern!==Number(playground.pattern))return false;
  if(playground.difficulty&&q.difficulty!==playground.difficulty)return false;
  if(playground.access==='free'&&q.premium)return false;
  if(playground.maxMinutes&&q.estimate>Number(playground.maxMinutes))return false;
  if(playground.search&&!(`${q.id} ${q.title}`).toLowerCase().includes(playground.search.toLowerCase()))return false;
  const st=status(state,q.id),last=state.attempts.filter(a=>a.question===q.id).at(-1);
  if(playground.progress==='unseen'&&attempted(q.id))return false;
  if(playground.progress==='retry'&&(!last||last.outcome==='Independent'))return false;
  if(playground.progress==='due'&&!(state.reviews[q.id]?.due<=today()))return false;
  if(playground.progress==='independent'&&!['Solved independently','Retained'].includes(st))return false;
  if(playground.progress==='bookmarked'&&!state.bookmarks.includes(q.id))return false;
  if(playground.progress==='covered'&&!attempted(q.id)&&!(q.sessions?.[0]?.day<=learnedDay))return false;
  return true;
 });
}
function drawPlayground(){
 const remaining=playgroundPool().filter(q=>!playground.seen.includes(q.id));
 if(!remaining.length){toast(playgroundPool().length?'Round complete. Reset the round to allow repeats, or change filters.':'No matching questions. Try fewer filters.');return;}
 const random=new Uint32Array(1);crypto.getRandomValues(random);
 const q=remaining[Math.floor((random[0]/4294967296)*remaining.length)];
 playground.current=q.id;playground.seen.push(q.id);playground.reveal=playground.mode==='guided';playground.hint=0;
 practiceContext={question:q.id,source:'playground',assisted:playground.mode==='guided'};
 render();
}
