function recount(d){d.newMinutes=d.questions.reduce((n,q)=>n+qmap[q].estimate,0);d.total=d.newMinutes+d.reviewMinutes+(d.lessonMinutes??(d.lesson?15:0))+(d.tinyMinutes||0)+(d.recallMinutes||0)+(d.reflectionMinutes||0)+(d.mock?60:0);d.overflow=Math.max(0,d.total-d.capacity);}
